quest_spawn_builder_t(quest_entry_original_t *spawn_entries)
    : spawns(spawn_entries), count(0) {}

quest_entry_original_t *take_next_ptr()
{
    quest_entry_original_t *result = &spawns[count];
    ++count;
    return result;
}

