int trigger_time_ms = 13000;
spawn = &spawns[builder.count];
while (trigger_time_ms < 0x96c8) {
    int spawn_count = wave / 8 + 1;

    spawn->pos = top_left;
    spawn->heading = 1.04719758f;
    spawn->set_spawn(
        SPAWN_ID_AI1_LIZARD_BLUE_TINT_1C,
        trigger_time_ms,
        spawn_count);
    ++builder.count;
    ++spawn;

    spawn->pos = top_right;
    spawn->heading = -1.04719758f;
    spawn->set_spawn(
        SPAWN_ID_AI1_LIZARD_BLUE_TINT_1C,
        trigger_time_ms,
        spawn_count);
    ++builder.count;
    ++spawn;

    spawn->pos = bottom_left;
    spawn->heading = -1.04719758f;
    spawn->set_spawn(
        SPAWN_ID_AI1_LIZARD_BLUE_TINT_1C,
        trigger_time_ms,
        spawn_count);
    ++builder.count;
    ++spawn;

    spawn->pos = bottom_right;
    spawn->heading = 3.926991f;
    spawn->set_spawn(
        SPAWN_ID_AI1_LIZARD_BLUE_TINT_1C,
        trigger_time_ms,
        spawn_count);
    ++builder.count;
    ++spawn;

    trigger_time_ms += 800;
    ++wave;
}

